from sim import Sim
import numpy as np

def run(kp, kd, steps=300):
    sim = Sim()
    qdes = sim.home_ctrl()  # joint targets
    for _ in range(steps):
        q = sim.data.qpos[7:7+sim.model.nu]
        qd = sim.data.qvel[6:6+sim.model.nu]  # maybe wrong? let's inspect later
        # joint velocities correspond after free joint 6 dof
        sim.data.ctrl[:] = np.clip(kp*(qdes-q) - kd*sim.data.qvel[6:6+sim.model.nu], sim.model.actuator_ctrlrange[:,0], sim.model.actuator_ctrlrange[:,1])
        sim.step(1)
    p = sim.pelvis_position(); t=sim.torso_up();
    return p, t, sim.distance_to_touch(), sim.distance_to_target()

for kp in [20,40,80,120,200]:
    for kd in [1,2,5,8,12]:
        try:
            p,t,dt,dd = run(kp,kd)
            print('kp kd',kp,kd,'pelvis',p,'torso',t,'touch',dt,'target',dd)
        except Exception as e:
            print('err',kp,kd,e)
