/bin/bash -lc "python - <<'PY'
from sim import Sim
import numpy as np

I = {
    'left_hip_pitch':2, 'left_knee':3, 'left_ankle':4,
    'right_hip_pitch':7, 'right_knee':8, 'right_ankle':9,
    'torso':10,
    'left_shoulder_pitch':11, 'left_elbow':14,
    'right_shoulder_pitch':15, 'right_elbow':18,
}

# sign vector per phase for each joint group: hip L, hip R, knee L, knee R, ankle L, ankle R, torso
# value multiplied by phase*amplitude.
patterns = []
for s_hl in [-1,1]:
  for s_hr in [-1,1]:
    for s_kl in [-1,1]:
      for s_kr in [-1,1]:
        for s_al in [-1,1]:
          for s_ar in [-1,1]:
            for s_t in [-1,1]:
              patterns.append((s_hl,s_hr,s_kl,s_kr,s_al,s_ar,s_t))

amp = dict(hip=0.45,knee=0.2,ankle=0.15,torso=0.12)

def eval_pat(pat):
    s_hl,s_hr,s_kl,s_kr,s_al,s_ar,s_t = pat
    sim = Sim(); base=sim.home_ctrl().copy()
    base[I['left_shoulder_pitch']] += -0.9
    base[I['right_shoulder_pitch']] += -0.9
    base[I['left_elbow']] += 0.9
    base[I['right_elbow']] += 0.9
    kp,kd=260,12
    # settle
    for _ in range(50):
      q=sim.data.qpos[7:]; qd=sim.data.qvel[6:6+sim.model.nu]
      tor=kp*(base-q)-kd*qd
      sim.data.ctrl[:] = np.clip(tor, sim.model.actuator_ctrlrange[:,0], sim.model.actuator_ctrlrange[:,1])
      sim.step(1)
    x0 = sim.pelvis_position()[0]
    for cyc in range(3):
      for phase in [1,-1]:
        for _ in range(90):
          qdes = base.copy()
          qdes[I['left_hip_pitch']] += phase*amp['hip']*s_hl
          qdes[I['right_hip_pitch']] += phase*amp['hip']*s_hr
          qdes[I['left_knee']] += phase*amp['knee']*s_kl
          qdes[I['right_knee']] += phase*amp['knee']*s_kr
          qdes[I['left_ankle']] += phase*amp['ankle']*s_al
          qdes[I['right_ankle']] += phase*amp['ankle']*s_ar
          qdes[I['torso']] += phase*amp['torso']*s_t
          q=sim.data.qpos[7:]; qd=sim.data.qvel[6:6+sim.model.nu]
          tor=kp*(qdes-q)-kd*qd
          sim.data.ctrl[:] = np.clip(tor, sim.model.actuator_ctrlrange[:,0], sim.model.actuator_ctrlrange[:,1])
          sim.step(1)
    p=sim.pelvis_position(); t=sim.torso_up();
    return p[0]-x0, p, t, sim.distance_to_target(), sim.distance_to_touch()

best=[]
for i,pat in enumerate(patterns):
    try:
        dx,p,t,dt,touch = eval_pat(pat)
        if len(best)<10 or dx>best[0][0]:
            best.append((dx,pat,p,t,dt,touch))
            best=sorted(best,key=lambda x:x[0])[-10:]
        print(i, 'dx', round(dx,3), 'pat', pat, 'p', np.round(p,3), 'torso', round(t,3), 'target', round(dt,3), 'touch', round(touch,3))
    except Exception as e:
        print('err', pat, e)

print('TOP')
for row in sorted(best,key=lambda x:x[0], reverse=True)[:10]:
    print(row)
